import type { VivaQuestion } from './types';

// The viva bank of Class 11 Accountancy (CBSE 2025-26): questions an examiner may ask about the project and the course, each with a short model answer. Format in types.ts; checked by validate.ts.
const VIVA_11: VivaQuestion[] = [
  // The project work itself.
  { id: 'v11-001', question: "Why did you choose this business for your project?", answer: "Give a true, specific reason: for example, a relative runs a similar shop, so I could see real bills and realistic prices. The business also has enough kinds of transactions, such as cash and credit sales, purchases, expenses and bank payments, to fill every book.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-002', question: "Where did you get your figures from?", answer: "Say honestly where they came from: for example, I studied the bills and price lists of a local kirana store and kept my amounts close to what such a shop really handles. Where a figure is assumed, I say so in the introduction.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-003', question: "Are the figures in your project real or assumed?", answer: "They are assumed but realistic, modelled on what I saw in a real business, and no private figures of any real business are disclosed. I kept them in proportion, so the rent, wages and sales make sense for a shop of that size.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-004', question: "How did you make sure your amounts were realistic?", answer: "I compared prices with real bills and current rates and kept sales above purchases by a sensible margin, so the gross profit came to a believable percentage. For example, a small stationery shop with monthly sales of ₹1,50,000 would not pay a monthly rent of ₹1,00,000.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'complex' },
  { id: 'v11-005', question: "What period does your project cover, and why that period?", answer: "Give your own period: for example, one month, April 2025, which is long enough to include every kind of transaction but short enough to record each one carefully. A month also gives a clear opening date and a clear closing date for the balances.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-006', question: "What is the purpose of the certificate in your project file?", answer: "The certificate, signed by the teacher, states that the student completed the project under guidance during the session. It confirms that the work is the student's own.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-007', question: "What did you write in the acknowledgement?", answer: "I thanked the people who helped me, such as my teacher, the principal, the shop owner who explained the bills to me, and my family. It is a short page of thanks, not part of the accounting work.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-008', question: "Why does your project file have an index?", answer: "The index lists every part of the file with its page number, so the examiner can turn straight to the journal, the ledger or the charts. It also shows that the file follows a logical order.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-009', question: "What did you write in the introduction to the business?", answer: "I described the business: its name, the owner, where it is, what it deals in, the date the books begin and the capital introduced. This tells the reader what the transactions are about before the accounts begin.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-010', question: "In what order are the parts of your project file arranged?", answer: "It opens with the certificate, the acknowledgement and the index, then the introduction to the business. Next come the accounting work and the charts, and it ends with the conclusion and the bibliography.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-011', question: "What is a bibliography, and what did you list in yours?", answer: "A bibliography lists the sources I used, such as the NCERT Accountancy textbook, the CBSE syllabus and the websites I checked for GST rates. It is placed at the end of the file and shows where my information came from.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-012', question: "What did you write in your conclusion?", answer: "I summed up what the accounts showed, such as the gross profit, the net profit and the financial position at the end, and what I learned by doing the work. It is my own reflection in a few lines, not a repeat of the introduction.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-013', question: "What is the name of your business, who owns it, and when did it start?", answer: "Answer in one breath with your own details: for example, Sharma Stationery Mart, owned by Ritu Sharma, started at Jaipur on 1 April 2025 with a capital of ₹2,00,000. Know these facts as well as your own name.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-014', question: "Which source of data did you use: primary or secondary?", answer: "My data is primary where I collected bills or asked the shop owner about prices and expenses, and secondary where I used the textbook and published GST rates. I named both kinds in the bibliography so every figure can be traced.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-015', question: "What assumptions did you state at the start of your project?", answer: "State your own: for example, that the business is a sole proprietorship, that the books follow the accrual basis and the going concern assumption, that all sales and purchases are within the state with GST at 18%, and that the period is one month. Stating them tells the examiner how to read the figures.", topicId: 'project', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-016', question: "Is your project your own work?", answer: "Yes; I chose the business, worked out every entry and drew every chart myself, while my teacher checked my progress. Everything I referred to is listed in the bibliography.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-017', question: "How long did it take you to complete the project?", answer: "Give your own timeline: for example, about six weeks, with the business chosen and the figures gathered in the first two weeks, the books written up over the next three, and the charts and conclusion in the last week.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-018', question: "How did you check your work?", answer: "I checked that every entry had equal debits and credits, that every posting reached the correct side of the correct account, and that the trial balance agreed. Then I checked that the Balance Sheet balanced and worked every total a second time.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-019', question: "Did you find any mistakes while doing the project, and how did you correct them?", answer: "Be honest and specific: for example, my trial balance first differed by ₹900 because I had not posted a cash sale of ₹900 to the Sales Account, and checking the postings one by one found it. I corrected the ledger before preparing the final accounts.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'complex' },
  { id: 'v11-020', question: "What did you learn from your project?", answer: "Give two or three real lessons: for example, I learned how one transaction travels from a bill to the journal, the ledger and the final accounts, and why accuracy at each step matters. I also understood why a business's profit is not the same as the cash it holds.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-021', question: "What would you do differently if you did the project again?", answer: "Name a real improvement: for example, I would record each transaction the day it happens instead of in batches, and I would add a bar diagram comparing two months. I would also prepare the vouchers first so that every entry has its evidence.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'complex' },
  { id: 'v11-022', question: "What difficulties did you face while preparing the project?", answer: "Mention a genuine difficulty and how you solved it: for example, I was unsure whether goods returned by a customer belonged in the sales returns book, so I checked the textbook and asked my teacher. Collecting real documents also took time because the shops were busy.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-023', question: "How is your project useful to the owner of the business?", answer: "It shows the owner the profit earned, which expenses are high, and what the business owns and owes, which helps in pricing, controlling costs and deciding whether to expand. A bank reconciliation also tells the owner whether the bank's record agrees with the business's own.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'complex' },
  { id: 'v11-024', question: "Did you use a computer for any part of the project?", answer: "Answer truthfully: for example, I wrote all the books by hand and used a spreadsheet only to draw the charts, then checked each angle and percentage myself. Either way, I can explain every figure on every page.", topicId: 'project', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-025', question: "What is Option 1 of the Class 11 project?", answer: "Option 1 is about source documents and vouchers: I collect the documents of a business's transactions, prepare a voucher for each, and record the transactions from the vouchers.", topicId: 'project', options: ['vouchers'], difficulty: 'easy' },
  { id: 'v11-026', question: "What source documents did you collect for your vouchers project?", answer: "Name your own: for example, cash memos, purchase and sales invoices, receipts, a debit note, a credit note, a cheque counterfoil and a pay-in-slip, each for a different kind of transaction. Every voucher in my file is supported by one of them.", topicId: 'project', options: ['vouchers'], difficulty: 'easy' },
  { id: 'v11-027', question: "How did you prepare a voucher from a source document?", answer: "I read the document for the date, the parties, the amount and what was bought, sold, paid or received, and decided which account is debited and which is credited. Then I filled in the voucher with its number, date, accounts, amount and narration, and attached the document behind it.", topicId: 'project', options: ['vouchers'], difficulty: 'medium' },
  { id: 'v11-028', question: "How did you number your vouchers, and why?", answer: "I numbered each type separately in date order, for example D-1, D-2 for debit vouchers and C-1, C-2 for credit vouchers. Serial numbers make every entry traceable and show at once if a voucher is missing.", topicId: 'project', options: ['vouchers'], difficulty: 'medium' },
  { id: 'v11-029', question: "Who prepared and signed the vouchers in your project?", answer: "I prepared them and signed as the preparer, and I showed where the authorised signatory, such as the proprietor, signs to approve each one. On a debit voucher I also left space for the signature of the person who received the cash.", topicId: 'project', options: ['vouchers'], difficulty: 'medium' },
  { id: 'v11-030', question: "How many vouchers did you prepare, and of which kinds?", answer: "Give your own numbers: for example, 20 vouchers, of which 8 were debit vouchers, 6 credit vouchers, 4 transfer vouchers and 2 journal (complex) vouchers, and 3 of the debit and credit vouchers were compound. Including every kind shows that I know when each is used.", topicId: 'project', options: ['vouchers'], difficulty: 'medium' },
  { id: 'v11-031', question: "What did you do with the vouchers after preparing them?", answer: "I recorded each voucher in the journal in date order, posted the entries to the ledger and balanced the accounts, then prepared a trial balance to check the arithmetic. This shows how a voucher becomes part of the books.", topicId: 'project', options: ['vouchers'], difficulty: 'medium' },
  { id: 'v11-032', question: "What did you use as evidence for a transaction that has no outside document, such as depreciation?", answer: "Depreciation, adjustments and closing entries have no bill from outside, so I prepared a transfer voucher, approved by the authorised person, with the working in the narration. That internal voucher is the evidence for the entry.", topicId: 'project', options: ['vouchers'], difficulty: 'complex' },
  { id: 'v11-033', question: "What did you use as evidence for wages paid in cash, where there is no bill?", answer: "I used a wages sheet signed by each worker on receiving the money as the source document, and prepared a debit voucher from it. An internal document approved by the owner is acceptable evidence when no outside bill exists.", topicId: 'project', options: ['vouchers'], difficulty: 'complex' },
  { id: 'v11-034', question: "What is Option 2 of the Class 11 project?", answer: "Option 2 is a bank reconciliation statement: from a given cash book (bank column) and pass book with 20 to 25 transactions, I find why the two balances differ and prepare a statement that reconciles them.", topicId: 'project', options: ['brs'], difficulty: 'easy' },
  { id: 'v11-035', question: "How many transactions did your bank reconciliation project have?", answer: "Give your own figure within the range: for example, 24 transactions in the month, since the syllabus asks for 20 to 25. That gave enough items of every kind of difference.", topicId: 'project', options: ['brs'], difficulty: 'easy' },
  { id: 'v11-036', question: "How did you find the items that cause the difference between the cash book and the pass book?", answer: "I ticked every entry that appears in both books, matching the date, the cheque number and the amount. The entries left unticked in either book are the causes of the difference, and each one goes into the statement.", topicId: 'project', options: ['brs'], difficulty: 'medium' },
  { id: 'v11-037', question: "Which balance did you start your bank reconciliation statement from, and why?", answer: "I started from the cash book balance because it is the business's own record, and adjusted it item by item to arrive at the pass book balance. Starting from the pass book balance works equally well if every sign is reversed.", topicId: 'project', options: ['brs'], difficulty: 'medium' },
  { id: 'v11-038', question: "How did you check that your bank reconciliation statement was correct?", answer: "After all the additions and deductions, the figure I reached was exactly the balance in the pass book on that date. I also prepared the amended cash book and checked that it reconciled to the same pass book balance.", topicId: 'project', options: ['brs'], difficulty: 'complex' },
  { id: 'v11-039', question: "In your project, which differences were timing differences and which were items still to be entered in the cash book?", answer: "Cheques issued but not presented and cheques deposited but not credited are timing differences that clear by themselves in the next few days. Bank charges, interest credited, direct deposits, payments under standing instructions and dishonoured cheques have to be entered in the cash book.", topicId: 'project', options: ['brs'], difficulty: 'complex' },
  { id: 'v11-040', question: "Why did the cash book and the pass book of your project differ at all?", answer: "The business and the bank record the same transactions on different dates, and each records some items the other does not yet know about, such as unpresented cheques or bank charges. Errors in either book also cause a difference.", topicId: 'project', options: ['brs'], difficulty: 'medium' },
  { id: 'v11-041', question: "Why did you also prepare an amended cash book in your bank reconciliation project?", answer: "Items such as bank charges, interest and direct deposits were not yet in the cash book, so I first corrected the cash book for them to find its true balance. The statement then had to explain only the timing differences, and the corrected balance is the one that goes into the Balance Sheet.", topicId: 'project', options: ['brs'], difficulty: 'complex' },
  { id: 'v11-042', question: "What is Option 3 of the Class 11 project?", answer: "Option 3 is a comprehensive project of a sole proprietor's business: I record a period's transactions in the journal, post them to the ledger, prepare a trial balance, and then the Trading and Profit and Loss Account and the Balance Sheet. The expenses, incomes, profit, assets and liabilities are also shown as pie charts or bar diagrams.", topicId: 'project', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-043', question: "In what order did you do the comprehensive project?", answer: "I journalised the transactions, posted them to the ledger and balanced each account, prepared the trial balance, and then made the Trading and Profit and Loss Account and the Balance Sheet with the adjustments. Last, I drew the charts and wrote the conclusion.", topicId: 'project', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-044', question: "How many transactions did you record in your comprehensive project, and why that many?", answer: "Give your own number: for example, about 30 transactions for April, enough to include purchases, sales, returns, expenses, incomes, a bank deposit, a fixed asset and drawings. Fewer would leave some books empty, and many more would add length without new learning.", topicId: 'project', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-045', question: "Which kinds of transactions did you deliberately include in your project, and why?", answer: "I included cash and credit purchases and sales, returns, a cheque payment, an expense paid in advance, a fixed asset bought and drawings, so that every book and every adjustment had something to show. A project with only cash sales would not test enough of the course.", topicId: 'project', options: ['comprehensive'], difficulty: 'complex' },
  { id: 'v11-046', question: "Why did you include drawings in your project?", answer: "Owners of small businesses do take cash or goods for personal use, so a drawings entry makes the books true to life. It also shows that drawings reduce capital in the Balance Sheet and are not an expense in the Profit and Loss Account.", topicId: 'project', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-047', question: "Why did you prepare the trial balance before the final accounts?", answer: "The trial balance checks the arithmetic of the ledger and lists every balance in one place, and the Trading and Profit and Loss Account and the Balance Sheet are prepared from it. Starting the final accounts from an agreed trial balance saves tracing errors later.", topicId: 'project', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-048', question: "What were your gross profit and net profit?", answer: "State your exact figures and what they mean: for example, a gross profit of ₹48,000 on sales of ₹1,60,000, which is 30%, and a net profit of ₹21,000 after indirect expenses of ₹27,000.", topicId: 'project', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-049', question: "What is your Balance Sheet total, and why do both sides agree?", answer: "Give your own total, for example ₹3,15,000 on each side. Both sides agree because every transaction was recorded with an equal debit and credit, so the assets equal the capital, including the net profit, plus the liabilities.", topicId: 'project', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-050', question: "Why did you include GST transactions in your project?", answer: "Real businesses charge and pay GST on most goods, so a few simple GST transactions made the books realistic. They also show that I can record the tax paid on purchases and the tax collected on sales correctly.", topicId: 'project', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-051', question: "How did you record GST in your project?", answer: "For an intra-state purchase of ₹10,000 at 18%, I debited Purchases ₹10,000, Input CGST ₹900 and Input SGST ₹900, and credited the supplier ₹11,800. On sales I credited Output CGST and Output SGST in the same way, and at the end of the month I set off the input tax against the output tax.", topicId: 'project', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-052', question: "Why did you record input GST and output GST in separate accounts?", answer: "Input GST is a credit the business can claim and output GST is tax it owes to the government, so keeping them apart shows each clearly and lets me work out the set-off at the end of the month. Netting them in every entry would hide how much tax was paid on purchases and how much was collected on sales.", topicId: 'project', options: ['vouchers', 'comprehensive'], difficulty: 'complex' },
  { id: 'v11-053', question: "How much GST was payable at the end of your period?", answer: "Work it out from your own figures: for example, output GST of ₹5,400 on sales less input tax credit of ₹3,600 on purchases leaves ₹1,800 payable, ₹900 as CGST and ₹900 as SGST. If not yet paid, it is shown as a current liability.", topicId: 'project', options: ['comprehensive'], difficulty: 'complex' },
  { id: 'v11-054', question: "What pie charts did you draw in your project?", answer: "I drew pie charts of the expenses, the incomes, the assets and the liabilities, each showing the share of every item in its total. A pie chart suits these because the parts make up one whole.", topicId: 'project', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-055', question: "How do you work out the angles of a pie chart from your figures?", answer: "Each item's angle is its share of the total multiplied by 360 degrees: for example, rent of ₹6,000 out of total expenses of ₹24,000 is one quarter, so its sector is 90 degrees. I checked that the angles added up to 360 degrees.", topicId: 'project', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-056', question: "What does your expenses pie chart tell you?", answer: "It shows which expense takes the largest share, for example salaries at 40% of the total, so the owner knows where control would save the most. A very small slice for advertisement may also help explain slow sales.", topicId: 'project', options: ['comprehensive'], difficulty: 'complex' },
  { id: 'v11-057', question: "Why did you use a bar diagram instead of a pie chart for some figures?", answer: "A bar diagram compares separate amounts side by side, such as sales, gross profit and net profit, which are not parts of one whole. A pie chart is the right choice only when the parts add up to a total.", topicId: 'project', options: ['comprehensive'], difficulty: 'complex' },
  { id: 'v11-058', question: "What does your chart of assets and liabilities tell you?", answer: "It shows where the business's money comes from and how it is used: if stock and debtors make up most of the assets, the money is tied up in trade. If capital is the largest part of the other side, the owner, not outsiders, finances most of the business.", topicId: 'project', options: ['comprehensive'], difficulty: 'complex' },
  { id: 'v11-059', question: "What should be written with every chart in the project?", answer: "Every chart needs a title, labels with the amounts or percentages, and a line below saying what it shows, for example that salaries are the largest expense. Without that reading, a chart is only a picture.", topicId: 'project', options: ['comprehensive'], difficulty: 'medium' },

  // Introduction to accounting.
  { id: 'v11-060', question: "What is accounting?", answer: "Accounting is the process of identifying, measuring, recording, classifying and summarising the financial transactions of a business, and interpreting and communicating the results to the people who use them.", topicId: 'introduction-to-accounting', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-061', question: "What is the difference between book-keeping and accounting?", answer: "Book-keeping is the recording part: entering transactions in the books of original entry and posting them to the ledger. Accounting is wider, because it includes book-keeping and goes on to summarise, analyse, interpret and communicate the results.", topicId: 'introduction-to-accounting', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-062', question: "Who are the users of accounting information?", answer: "Internal users are the owner and the managers; external users include creditors, banks and other lenders, investors, the government and tax authorities, and customers. Each needs the information for a different decision.", topicId: 'introduction-to-accounting', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-063', question: "What are the qualitative characteristics of accounting information?", answer: "Reliability, relevance, understandability and comparability. Information that is reliable but arrives too late, or that cannot be compared with last year, is of little use to a decision-maker.", topicId: 'introduction-to-accounting', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-064', question: "What are the limitations of accounting?", answer: "Accounting records only what can be measured in money, so the skill of the staff or the loyalty of customers is left out. Assets are recorded at historical cost, which ignores changes in prices, and estimates such as depreciation involve personal judgement.", topicId: 'introduction-to-accounting', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-065', question: "What is the difference between capital and drawings?", answer: "Capital is the money or assets the owner invests in the business, and drawings are the cash or goods the owner takes out for personal use. Drawings reduce capital.", topicId: 'introduction-to-accounting', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-066', question: "What is a business transaction?", answer: "A transaction is an exchange of money or money's worth between two parties that changes the financial position of the business, such as buying goods worth ₹20,000 on credit. An event is recorded only when it can be measured in money.", topicId: 'introduction-to-accounting', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-067', question: "What is the difference between assets and liabilities?", answer: "Assets are resources the business owns or controls that will bring future benefit, such as machinery, stock, debtors and cash. Liabilities are amounts the business owes to outsiders, such as creditors and bank loans.", topicId: 'introduction-to-accounting', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-068', question: "Who are debtors and who are creditors?", answer: "Debtors are persons who owe money to the business, mostly because goods were sold to them on credit. Creditors are persons to whom the business owes money, mostly for goods bought on credit.", topicId: 'introduction-to-accounting', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-069', question: "What is the difference between revenue, income and gain?", answer: "Revenue is the amount earned from the normal activities of the business, such as sales or commission. Income is the profit left after expenses are deducted from revenue, while a gain is a profit from an incidental event, such as selling an old machine for more than its book value.", topicId: 'introduction-to-accounting', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-070', question: "What is the difference between an expense and an expenditure?", answer: "An expense is a cost used up in earning the revenue of the current period, such as rent or wages, and goes to the Profit and Loss Account. An expenditure is any spending, and when its benefit lasts beyond the year, as with furniture, it becomes an asset.", topicId: 'introduction-to-accounting', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-071', question: "Is accounting an information system?", answer: "Yes; it collects data about transactions, processes it through the journal, the ledger and the trial balance, and communicates the results through financial statements to users who make decisions. Like any information system, its output is only as good as the data put in.", topicId: 'introduction-to-accounting', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'complex' },

  // Theory base, accounting standards and GST.
  { id: 'v11-072', question: "What is meant by GAAP?", answer: "Generally Accepted Accounting Principles are the rules, concepts and conventions, developed through practice and by authoritative bodies, that accountants follow so that financial statements are uniform and comparable.", topicId: 'theory-base', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-073', question: "What are the fundamental accounting assumptions?", answer: "Going concern, consistency and accrual. If the financial statements say nothing about them, the reader may take it that they were followed, and any departure must be disclosed.", topicId: 'theory-base', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-074', question: "What is the going concern assumption?", answer: "It assumes that the business will continue for the foreseeable future and has no intention of closing down or sharply cutting its operations. That is why fixed assets are shown at cost less depreciation and not at what they would fetch if sold today.", topicId: 'theory-base', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-075', question: "How does the business entity concept apply in your project?", answer: "The business is treated as separate from its owner, so when the owner invests ₹2,00,000, the business shows that amount as capital owed to the owner. If the owner's personal bills are paid from business cash, they are recorded as drawings, not as business expenses.", topicId: 'theory-base', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-076', question: "What is the matching concept?", answer: "The expenses of a period are matched with the revenues earned in that period so that the profit is fair. If the rent for March is unpaid on 31 March, it is still charged to that year as outstanding rent.", topicId: 'theory-base', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-077', question: "What is the dual aspect concept?", answer: "Every transaction has two equal and opposite effects, so for every debit there is a credit of the same amount. This is the basis of the accounting equation, Assets = Liabilities + Capital.", topicId: 'theory-base', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-078', question: "What is the prudence (conservatism) concept?", answer: "Profits are not anticipated, but every likely loss is provided for: closing stock is valued at cost or net realisable value, whichever is lower, and a provision is made for doubtful debts. This keeps profit and assets from being overstated.", topicId: 'theory-base', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-079', question: "What is the consistency concept, and why does it matter?", answer: "Once a method, such as the straight line method of depreciation, is chosen, it is followed year after year, so the results of different years can be compared. A change is made only for a good reason, and its effect is disclosed.", topicId: 'theory-base', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-080', question: "What is the materiality concept?", answer: "Only items whose amount or nature could affect a user's decision need separate attention or disclosure. A stapler costing ₹200 is written off as an expense although it lasts for years, because its effect is trivial.", topicId: 'theory-base', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-081', question: "What is the revenue recognition concept?", answer: "Revenue is recorded when it is earned, that is, when goods are sold or services rendered and the right to receive payment arises, not when the cash comes in. A credit sale made on 28 March is revenue of that year even if the customer pays in April.", topicId: 'theory-base', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-082', question: "What is the difference between the cash basis and the accrual basis of accounting?", answer: "On the cash basis only the cash received and paid is recorded, so outstanding expenses and accrued incomes are ignored. On the accrual basis, which a business follows, revenues and expenses are recorded when they arise, whether or not cash has moved.", topicId: 'theory-base', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-083', question: "What are accounting standards?", answer: "Accounting standards are written statements of the rules for recognising, measuring, presenting and disclosing particular transactions in financial statements. In India they are formulated by the Accounting Standards Board of the Institute of Chartered Accountants of India.", topicId: 'theory-base', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-084', question: "What are Ind AS?", answer: "Ind AS are the Indian Accounting Standards converged with the International Financial Reporting Standards (IFRS), applied by listed companies and other large companies. A sole proprietor's business, like the one in my project, follows the Accounting Standards (AS) instead.", topicId: 'theory-base', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-085', question: "What is GST?", answer: "GST, the Goods and Services Tax, is a single destination-based indirect tax on the supply of goods and services. It came into force on 1 July 2017 and replaced many older taxes, such as VAT, excise duty and service tax.", topicId: 'theory-base', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-086', question: "What is the difference between CGST, SGST and IGST?", answer: "On a supply within a state, the tax is split equally into CGST for the Centre and SGST for the state, for example 9% each when the rate is 18%. On a supply from one state to another, the whole tax is IGST, collected by the Centre.", topicId: 'theory-base', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-087', question: "What is input tax credit?", answer: "Input tax credit is the GST a registered business pays on its purchases, which it sets off against the GST it collects on its sales. The business then pays the government only the difference.", topicId: 'theory-base', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },

  // The accounting equation.
  { id: 'v11-088', question: "What is the accounting equation?", answer: "Assets = Liabilities + Capital. It holds after every transaction because every transaction has a dual effect.", topicId: 'accounting-equation', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-089', question: "Why is the accounting equation always in balance?", answer: "Every transaction changes at least two items by equal amounts, either changing both sides equally or raising one asset while lowering another. So total assets always equal the claims of outsiders and the owner.", topicId: 'accounting-equation', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-090', question: "How does a credit purchase of goods for ₹30,000 affect the accounting equation?", answer: "Stock, an asset, rises by ₹30,000 and creditors, a liability, rise by ₹30,000, so both sides increase equally. Capital is not affected.", topicId: 'accounting-equation', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-091', question: "How does selling goods costing ₹10,000 for ₹14,000 in cash affect the accounting equation?", answer: "Cash rises by ₹14,000 and stock falls by ₹10,000, so total assets rise by ₹4,000. Capital rises by the profit of ₹4,000, so the equation still balances.", topicId: 'accounting-equation', options: ['vouchers', 'comprehensive'], difficulty: 'complex' },
  { id: 'v11-092', question: "How do drawings affect the accounting equation?", answer: "Drawings of ₹5,000 in cash reduce cash, an asset, by ₹5,000 and reduce capital by the same ₹5,000. Liabilities do not change.", topicId: 'accounting-equation', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-093', question: "How does paying a creditor ₹8,000 by cheque affect the accounting equation?", answer: "The bank balance, an asset, falls by ₹8,000 and creditors, a liability, fall by ₹8,000, so both sides decrease equally.", topicId: 'accounting-equation', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-094', question: "How does paying rent in cash affect the accounting equation?", answer: "Paying rent of ₹6,000 in cash lowers cash by ₹6,000 and lowers capital by ₹6,000, because an expense reduces the profit and so the owner's claim.", topicId: 'accounting-equation', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-095', question: "Can a transaction change only one side of the accounting equation?", answer: "Yes, when it exchanges one asset for another or one liability for another: buying furniture for ₹12,000 in cash raises furniture and lowers cash, so total assets are unchanged. The equation balances because the two changes cancel on that side.", topicId: 'accounting-equation', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-096', question: "What is the modern rule of debit and credit based on the accounting equation?", answer: "An increase in an asset or an expense is debited, and an increase in a liability, capital or revenue is credited; decreases are recorded the opposite way. Because it follows from the equation, debits always equal credits.", topicId: 'accounting-equation', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-097', question: "If assets are ₹5,00,000 and liabilities are ₹1,80,000, what is the capital?", answer: "Capital is assets minus liabilities: ₹5,00,000 minus ₹1,80,000, which is ₹3,20,000.", topicId: 'accounting-equation', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },

  // Source documents, vouchers and the journal.
  { id: 'v11-098', question: "What is a source document?", answer: "A source document is the original written evidence of a transaction, such as a cash memo, an invoice, a receipt, a debit note or a pay-in-slip. It gives the date, the parties, the amount and the nature of the transaction.", topicId: 'journal-entries', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-099', question: "Is a voucher a source document?", answer: "Not an accounting voucher. The bill, invoice or receipt is the source document (sometimes called a source voucher), the original evidence from the transaction; the accounting voucher is prepared from it inside the business, showing the accounts debited and credited, and the entry is recorded from the voucher with the source document attached as its support.", topicId: 'journal-entries', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-100', question: "Who signs a voucher?", answer: "The person who prepares the voucher signs it, and an authorised signatory, such as the proprietor or the manager, signs to approve it. On a payment voucher the person receiving the money also signs, as proof of payment.", topicId: 'journal-entries', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-101', question: "What is the difference between a debit voucher and a credit voucher?", answer: "A debit voucher records a cash payment, such as rent paid, and names the account debited. A credit voucher records a cash receipt, such as cash sales, and names the account credited.", topicId: 'journal-entries', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-102', question: "What is a transfer voucher?", answer: "A transfer voucher records a non-cash transaction, such as goods sold on credit or depreciation charged, where no cash comes in or goes out.", topicId: 'journal-entries', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-103', question: "What is the difference between a compound voucher and a complex voucher?", answer: "A compound voucher has one debit and several credits, or one credit and several debits. A complex (journal) voucher has several debits and several credits together.", topicId: 'journal-entries', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-104', question: "What details should a good voucher contain?", answer: "The name of the business, a serial number, the date, the accounts debited and credited with the amounts in figures and words, a narration, and the signatures of the preparer and the authorised person. It should be supported by its source document.", topicId: 'journal-entries', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-105', question: "What is a journal?", answer: "The journal is the book of original entry in which transactions are first recorded in date order, showing the account debited, the account credited, the amounts and a narration.", topicId: 'journal-entries', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-106', question: "What is a narration, and why is it written?", answer: "A narration is a short explanation below a journal entry saying what the transaction was, for example 'Being goods sold to Kapoor Traders on credit'. It lets anyone checking the books understand the entry without opening the voucher.", topicId: 'journal-entries', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-107', question: "What is a compound journal entry?", answer: "A compound entry has more than one debit or more than one credit: either one transaction that affects more than two accounts, such as cash received from a debtor with discount allowed, or transactions of the same kind on the same date combined, such as rent and wages paid together in cash.", topicId: 'journal-entries', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-108', question: "What are the traditional rules of debit and credit?", answer: "Personal account: debit the receiver and credit the giver. Real account: debit what comes in and credit what goes out. Nominal account: debit all expenses and losses and credit all incomes and gains.", topicId: 'journal-entries', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-109', question: "What is an opening entry?", answer: "The opening entry brings the closing balances of the previous year into the new books: the assets are debited, the liabilities are credited, and Capital A/c is credited with the excess of assets over liabilities.", topicId: 'journal-entries', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-110', question: "How do you record goods given away as free samples?", answer: "Debit Advertisement A/c (or Free Samples A/c) and credit Purchases A/c with the cost of the goods. The goods were bought for resale, so purchases are reduced, and their cost becomes a selling expense.", topicId: 'journal-entries', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-111', question: "How are trade discount and cash discount recorded?", answer: "Trade discount is not recorded at all; the transaction is entered at the price after deducting it. Cash discount allowed is debited to Discount Allowed A/c as a loss, and cash discount received is credited to Discount Received A/c as a gain.", topicId: 'journal-entries', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-112', question: "What is the entry for a credit purchase of goods worth ₹20,000 plus GST at 18% within the state?", answer: "Debit Purchases ₹20,000, Input CGST ₹1,800 and Input SGST ₹1,800, and credit the supplier ₹23,600. The tax is split equally because the supply is within the state.", topicId: 'journal-entries', options: ['vouchers', 'comprehensive'], difficulty: 'complex' },
  { id: 'v11-113', question: "How do you record a credit sale to a customer in another state?", answer: "The customer is debited with the price plus IGST, and Sales and Output IGST are credited: for goods of ₹10,000 at 5%, the customer is debited ₹10,500, Sales is credited ₹10,000 and Output IGST ₹500.", topicId: 'journal-entries', options: ['vouchers', 'comprehensive'], difficulty: 'complex' },

  // The ledger.
  { id: 'v11-114', question: "What is a ledger?", answer: "The ledger is the principal book of accounts, in which all the entries relating to one account are brought together in one place so that its balance can be found.", topicId: 'ledger', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-115', question: "Why is the ledger called the principal book of accounts?", answer: "The final accounts are prepared from the ledger balances, and only the ledger shows the net position of each account. The journal shows each transaction but not, for example, the total a customer owes.", topicId: 'ledger', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-116', question: "What is posting?", answer: "Posting is transferring each entry from the journal or a subsidiary book to the correct side of the account concerned in the ledger.", topicId: 'ledger', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-117', question: "Why are 'To' and 'By' written in a ledger account?", answer: "By convention, 'To' is written before the account name on the debit side and 'By' on the credit side. The name written is the other account of the same entry.", topicId: 'ledger', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-118', question: "How do you balance a ledger account?", answer: "Total both sides, write the difference on the smaller side as Balance c/d so the totals agree, and bring it down on the opposite side as Balance b/d at the start of the next period. A debit balance is brought down on the debit side and a credit balance on the credit side.", topicId: 'ledger', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-119', question: "What does a debit balance in a customer's account mean?", answer: "It means the customer owes that amount to the business, so the customer is a debtor and the balance is shown under current assets.", topicId: 'ledger', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-120', question: "Which ledger accounts are balanced and which are closed by transfer?", answer: "Personal and real accounts, such as debtors, creditors, cash and machinery, are balanced and carried forward because they continue into the next period. Nominal accounts, such as wages, rent and sales, are closed by transfer to the Trading Account or the Profit and Loss Account.", topicId: 'ledger', options: ['vouchers', 'comprehensive'], difficulty: 'complex' },
  { id: 'v11-121', question: "What is the ledger folio column used for?", answer: "In the journal, the ledger folio column records the page number of the ledger account to which the entry was posted. It shows that the posting has been done and lets anyone trace it from the journal to the ledger.", topicId: 'ledger', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-122', question: "Can the cash account have a credit balance?", answer: "No; a business cannot pay out more cash than it has, so cash in hand can never be less than nil. A credit balance in the cash account means there is an error.", topicId: 'ledger', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-123', question: "What are the kinds of accounts under the traditional classification?", answer: "Personal accounts of natural, artificial and representative persons; real accounts of tangible and intangible assets; and nominal accounts of expenses, losses, incomes and gains.", topicId: 'ledger', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-124', question: "What is the difference between the journal and the ledger?", answer: "The journal records transactions in date order and is the book of original entry; the ledger groups the same entries account by account and is the book of final entry. The trial balance is prepared from the ledger, not from the journal.", topicId: 'ledger', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },

  // The cash book.
  { id: 'v11-125', question: "What is a cash book?", answer: "A cash book records all cash receipts and payments in date order, receipts on the debit side and payments on the credit side.", topicId: 'cash-book', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-126', question: "Why is no separate Cash Account opened in the ledger when a cash book is kept?", answer: "The cash book itself works as the Cash Account, with receipts on the debit side and payments on the credit side, and it is balanced like a ledger account. Only the other account of each entry is posted to the ledger.", topicId: 'cash-book', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-127', question: "What is a cash book with a bank column?", answer: "It has two amount columns on each side, Cash and Bank, so cash and bank transactions are recorded in one book and both balances can be seen together.", topicId: 'cash-book', options: ['brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-128', question: "What is a contra entry?", answer: "A contra entry affects both the cash and the bank columns, such as depositing cash into the bank or withdrawing cash from the bank for office use. It is marked C in the folio column and is not posted to the ledger, because both accounts are in the cash book.", topicId: 'cash-book', options: ['brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-129', question: "How is a cheque received and deposited on the same day recorded?", answer: "It is entered directly in the bank column on the debit side, because the money goes straight into the bank. If it is deposited on a later day, it is first entered in the cash column and then deposited by a contra entry.", topicId: 'cash-book', options: ['brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-130', question: "What does a credit balance in the bank column of the cash book mean?", answer: "It means the business has withdrawn more than it has in the bank, that is, an overdraft, so the business owes the bank. It is shown as a liability in the Balance Sheet.", topicId: 'cash-book', options: ['brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-131', question: "What is petty cash?", answer: "Petty cash is a small sum kept for small day-to-day expenses, such as postage, stationery, tea and auto fares, and recorded by the petty cashier in a petty cash book.", topicId: 'cash-book', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-132', question: "What is the imprest system of petty cash?", answer: "The petty cashier receives a fixed sum, the imprest, at the start of a period, say ₹5,000. At the end of the period the main cashier pays back exactly what was spent, so the petty cashier starts every period with ₹5,000 again.", topicId: 'cash-book', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-133', question: "If ₹3,650 was spent out of a petty cash imprest of ₹5,000, how much is reimbursed?", answer: "₹3,650 is reimbursed, the amount spent, which brings petty cash back to ₹5,000. Before the reimbursement the petty cashier held ₹1,350.", topicId: 'cash-book', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-134', question: "Why does a petty cash book have analysis columns?", answer: "Each column collects one kind of small expense, such as postage, stationery or conveyance, so only the column totals are posted to the ledger at the end of the period. This saves posting dozens of tiny amounts one by one.", topicId: 'cash-book', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-135', question: "Why is a cash book especially useful to a small shop?", answer: "The owner can see the cash and bank balances at any moment and compare them with the cash actually in the drawer, so shortages and errors show up at once. It also removes the need to post every cash entry to a separate Cash Account.", topicId: 'cash-book', options: ['vouchers', 'brs', 'comprehensive'], difficulty: 'complex' },

  // Subsidiary books.
  { id: 'v11-136', question: "What are subsidiary books?", answer: "Subsidiary books are special journals for transactions of one kind that happen often, such as credit purchases, credit sales and returns, so that the journal is not crowded.", topicId: 'subsidiary-books', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-137', question: "Which subsidiary books did you use?", answer: "The cash book, the purchases book, the sales book, the purchases returns book and the sales returns book, with the journal proper for everything that fits none of them. Name only the ones that appear in your own project.", topicId: 'subsidiary-books', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-138', question: "What is recorded in the purchases book?", answer: "Only credit purchases of goods bought for resale. Cash purchases go to the cash book, and assets bought on credit go to the journal proper.", topicId: 'subsidiary-books', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-139', question: "Where would you record the credit purchase of a computer for office use?", answer: "In the journal proper, not in the purchases book, because the computer is a fixed asset and not goods for resale. Computer A/c is debited and the supplier is credited.", topicId: 'subsidiary-books', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-140', question: "What is a debit note?", answer: "A debit note is sent by a buyer to a supplier when goods are returned, saying that the supplier's account has been debited with the stated amount. It is the source document for the purchases returns book.", topicId: 'subsidiary-books', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-141', question: "What is a credit note?", answer: "A credit note is sent by a seller to a customer who has returned goods, saying that the customer's account has been credited with the stated amount. It is the source document for the sales returns book.", topicId: 'subsidiary-books', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-142', question: "What is the difference between an invoice and a cash memo?", answer: "An invoice is issued for a credit sale and is the source of the entry in the sales book, while a cash memo is issued for a cash sale and supports an entry in the cash book. Both show the goods, the quantity, the rate and the amount.", topicId: 'subsidiary-books', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-143', question: "Why is trade discount not recorded in the books?", answer: "Trade discount is a reduction in the list price allowed at the time of sale, so the transaction is recorded at the price after deducting it, which is the amount actually owed. Cash discount, allowed for prompt payment, is recorded.", topicId: 'subsidiary-books', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-144', question: "How is the sales book posted to the ledger?", answer: "Each customer's account is debited with the full invoice value of each sale, and the period's total of goods sold is credited to Sales Account. Where the book has GST columns, their totals are credited to Output CGST and Output SGST accounts.", topicId: 'subsidiary-books', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-145', question: "Why did you add GST columns to your purchases and sales books?", answer: "GST columns keep the tax apart from the value of the goods, so the totals of input or output CGST and SGST can be posted to their own accounts. The supplier or customer is entered with the total invoice value, including the tax.", topicId: 'subsidiary-books', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-146', question: "What is the journal proper used for?", answer: "It records transactions that fit no special book, such as opening and closing entries, rectification and adjustment entries, credit purchase or sale of assets, and goods taken by the owner.", topicId: 'subsidiary-books', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-147', question: "Goods with a list price of ₹50,000 are sold on credit within the state at 10% trade discount and 18% GST: what is the invoice value?", answer: "The price after the trade discount of ₹5,000 is ₹45,000. GST at 18% on it is ₹8,100, that is CGST ₹4,050 and SGST ₹4,050, so the invoice value is ₹53,100.", topicId: 'subsidiary-books', options: ['vouchers', 'comprehensive'], difficulty: 'complex' },
  { id: 'v11-148', question: "What are the advantages of keeping subsidiary books?", answer: "Work can be divided among several people, posting is quicker because only totals go to accounts such as Purchases and Sales, and each kind of transaction can be totalled at a glance. Errors are also easier to locate.", topicId: 'subsidiary-books', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-149', question: "Where is the return of goods bought for cash recorded?", answer: "If the supplier refunds the money in cash, the refund is recorded on the receipts side of the cash book, with Purchases Returns A/c credited. The purchases returns book holds only returns of goods bought on credit.", topicId: 'subsidiary-books', options: ['vouchers', 'comprehensive'], difficulty: 'complex' },

  // Bank reconciliation statement.
  { id: 'v11-150', question: "What is a bank reconciliation statement?", answer: "It is a statement prepared on a given date that explains the difference between the bank balance shown by the cash book and the balance shown by the pass book, by listing the items that cause it.", topicId: 'bank-reconciliation', options: ['brs'], difficulty: 'easy' },
  { id: 'v11-151', question: "Is a bank reconciliation statement a part of the books of account?", answer: "No; it is only a statement prepared to explain the difference, not an account, and nothing is posted from it. The items missing from the cash book are entered in the cash book separately.", topicId: 'bank-reconciliation', options: ['brs'], difficulty: 'easy' },
  { id: 'v11-152', question: "What is the difference between a cash book and a pass book?", answer: "The cash book is kept by the business, with deposits on the debit side, while the pass book (bank statement) is the copy of the business's account kept by the bank, where deposits appear as credits. So a favourable balance is a debit in the cash book and a credit in the pass book.", topicId: 'bank-reconciliation', options: ['brs'], difficulty: 'easy' },
  { id: 'v11-153', question: "What are a favourable and an unfavourable bank balance?", answer: "A favourable balance means the business has money in the bank: a debit balance in the cash book and a credit balance in the pass book. An unfavourable balance is an overdraft: a credit balance in the cash book and a debit balance in the pass book.", topicId: 'bank-reconciliation', options: ['brs'], difficulty: 'easy' },
  { id: 'v11-154', question: "Why is a cheque issued but not presented added to the cash book balance in the bank reconciliation statement?", answer: "When the cheque was issued, the cash book was credited and its balance fell, but the bank has not paid it yet, so the pass book balance is still higher. Adding it back to the cash book balance brings it to the pass book figure.", topicId: 'bank-reconciliation', options: ['brs'], difficulty: 'medium' },
  { id: 'v11-155', question: "Why are cheques deposited but not yet credited deducted from the cash book balance?", answer: "The cash book was debited when the cheques were deposited, but the bank has not yet collected them, so the pass book balance is lower by that amount. Deducting them from the cash book balance gives the pass book balance.", topicId: 'bank-reconciliation', options: ['brs'], difficulty: 'medium' },
  { id: 'v11-156', question: "How are bank charges treated in the bank reconciliation statement?", answer: "The bank has debited the charges in the pass book, but the business has not yet recorded them, so the pass book balance is lower. Starting from the cash book balance, the charges are deducted.", topicId: 'bank-reconciliation', options: ['brs'], difficulty: 'medium' },
  { id: 'v11-157', question: "How is interest credited by the bank treated in the bank reconciliation statement?", answer: "Interest credited by the bank raises the pass book balance but is not yet in the cash book, so it is added to the cash book balance. Dividends collected by the bank are treated the same way.", topicId: 'bank-reconciliation', options: ['brs'], difficulty: 'medium' },
  { id: 'v11-158', question: "How is a deposited cheque that is dishonoured treated in the bank reconciliation statement?", answer: "When the cheque is dishonoured, the bank debits the account and the pass book balance falls, but the cash book still shows the money as received. So the amount is deducted from the cash book balance.", topicId: 'bank-reconciliation', options: ['brs'], difficulty: 'medium' },
  { id: 'v11-159', question: "How is an amount paid by a customer directly into the bank shown in the statement?", answer: "The customer's direct transfer raises the pass book balance before the business knows of it, so it is added to the cash book balance.", topicId: 'bank-reconciliation', options: ['brs'], difficulty: 'medium' },
  { id: 'v11-160', question: "How are payments made by the bank under standing instructions shown in the statement?", answer: "Payments such as an insurance premium or a loan instalment paid by the bank on standing instructions reduce only the pass book balance, so they are deducted from the cash book balance.", topicId: 'bank-reconciliation', options: ['brs'], difficulty: 'medium' },
  { id: 'v11-161', question: "If the cash book shows ₹25,000, cheques issued but not presented are ₹6,000 and bank charges are ₹200, what does the pass book show?", answer: "₹25,000 plus ₹6,000 minus ₹200 gives a pass book balance of ₹30,800. The cheques are added because the bank has not yet paid them, and the charges are deducted because only the bank has recorded them.", topicId: 'bank-reconciliation', options: ['brs'], difficulty: 'complex' },
  { id: 'v11-162', question: "How do you prepare the statement when the cash book shows an overdraft?", answer: "The overdraft is the starting figure, and every adjustment works the opposite way to a favourable balance: cheques issued but not presented are deducted and cheques deposited but not credited are added. The result is the overdraft as per the pass book.", topicId: 'bank-reconciliation', options: ['brs'], difficulty: 'complex' },
  { id: 'v11-163', question: "A deposit of ₹4,500 was entered in the cash book as ₹5,400: how is it treated in the statement?", answer: "The cash book balance is overstated by ₹900, so ₹900 is deducted from the cash book balance in the statement. The cash book itself should also be corrected.", topicId: 'bank-reconciliation', options: ['brs'], difficulty: 'complex' },
  { id: 'v11-164', question: "Which bank balance is shown in the Balance Sheet: the cash book figure or the pass book figure?", answer: "The amended cash book balance, corrected for bank charges, interest, direct deposits and similar items. Cheques issued or deposited are already the business's completed transactions, so the pass book figure, which leaves them out, is not used.", topicId: 'bank-reconciliation', options: ['brs', 'comprehensive'], difficulty: 'complex' },
  { id: 'v11-165', question: "Why should a bank reconciliation statement be prepared regularly?", answer: "It catches errors and omissions in either book quickly, shows cheques that are taking too long to clear, and discourages fraud by those handling money. It also confirms the true bank balance for the Balance Sheet.", topicId: 'bank-reconciliation', options: ['brs'], difficulty: 'medium' },

  // The trial balance.
  { id: 'v11-166', question: "What is a trial balance?", answer: "A trial balance is a statement of the debit and credit balances of all ledger accounts on a given date, prepared to check the arithmetical accuracy of the books.", topicId: 'trial-balance', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-167', question: "Why does your trial balance agree, and does that prove the books are free of errors?", answer: "It agrees because every debit was matched by an equal credit and every account was posted and balanced correctly. It does not prove the books are free of errors, since a transaction omitted altogether, a posting to the wrong account on the correct side, an error of principle and compensating errors all leave the totals equal.", topicId: 'trial-balance', options: ['vouchers', 'comprehensive'], difficulty: 'complex' },
  { id: 'v11-168', question: "What are the objectives of preparing a trial balance?", answer: "It checks the arithmetical accuracy of the ledger, gives a summary of all the balances in one place for preparing the final accounts, and helps to locate errors when it does not agree.", topicId: 'trial-balance', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-169', question: "What would you do if your trial balance did not agree?", answer: "Recheck the totals of the trial balance and of each account, check that every balance is entered on the correct side, and then check the postings from the books of original entry. If the difference still cannot be found and the accounts must be prepared, I would put it in a Suspense Account.", topicId: 'trial-balance', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-170', question: "On which side of the trial balance do drawings appear?", answer: "On the debit side, because drawings reduce the owner's capital; they are shown separately from capital, which is on the credit side.", topicId: 'trial-balance', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-171', question: "Which balances appear on the credit side of the trial balance?", answer: "Capital, liabilities such as creditors and loans, incomes and gains such as sales, commission received and discount received, purchases returns, and provisions.", topicId: 'trial-balance', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-172', question: "Why do sales returns appear on the debit side of the trial balance?", answer: "Sales returns reduce sales, so the Sales Returns Account has a debit balance, the opposite of the Sales Account. It is deducted from sales in the Trading Account.", topicId: 'trial-balance', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-173', question: "Is closing stock shown in the trial balance?", answer: "Opening stock appears on the debit side, but closing stock is usually given outside the trial balance as an adjustment. If closing stock is already in the trial balance, it has been adjusted through purchases, so it goes only to the Balance Sheet.", topicId: 'trial-balance', options: ['comprehensive'], difficulty: 'complex' },
  { id: 'v11-174', question: "What is the balance method of preparing a trial balance?", answer: "Only the balance of each ledger account is entered, debit balances in one column and credit balances in the other. It is the only method in the CBSE syllabus, and it leads straight to the final accounts.", topicId: 'trial-balance', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-175', question: "On which side do the provision for doubtful debts and the provision for depreciation appear?", answer: "Both appear on the credit side, because they are credit balances set aside against debtors and fixed assets respectively.", topicId: 'trial-balance', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-176', question: "Is a trial balance an account?", answer: "No; it is a statement prepared on a date, not an account, so it has no 'To' and 'By' and no balance of its own.", topicId: 'trial-balance', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },

  // Rectification of errors.
  { id: 'v11-177', question: "What are the types of errors in accounting?", answer: "Errors of omission, errors of commission, errors of principle and compensating errors. Errors of commission include wrong posting, wrong totalling and wrong carrying forward.", topicId: 'rectification-of-errors', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-178', question: "What is an error of omission?", answer: "A complete omission leaves a transaction out of the books altogether and does not affect the trial balance. A partial omission, such as forgetting to post one side of an entry, does affect it.", topicId: 'rectification-of-errors', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-179', question: "What is an error of commission?", answer: "It is a wrong amount, wrong account or wrong side, made while recording, posting, totalling or carrying forward. Some affect the trial balance, while others, such as posting to the wrong person's account on the correct side, do not.", topicId: 'rectification-of-errors', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-180', question: "What is an error of principle?", answer: "An error of principle breaks a basic accounting rule, such as treating capital expenditure as revenue expenditure: debiting furniture bought for ₹15,000 to Purchases A/c. It does not affect the trial balance.", topicId: 'rectification-of-errors', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-181', question: "What is a compensating error?", answer: "Two or more errors whose effects cancel out, so the trial balance still agrees: for example, the Sales Account undercast by ₹1,000 and the Wages Account also undercast by ₹1,000.", topicId: 'rectification-of-errors', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-182', question: "What is a one-sided error?", answer: "An error that affects only one account, such as wrong totalling or posting only one side of an entry, so the trial balance does not agree. After the difference is put in a Suspense Account, it is rectified with Suspense A/c as the other side.", topicId: 'rectification-of-errors', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-183', question: "What is a Suspense Account?", answer: "A Suspense Account is a temporary account that holds the difference in a trial balance that does not agree, so that the final accounts can be prepared. It is closed when the errors are found and rectified.", topicId: 'rectification-of-errors', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-184', question: "If the purchases book is undercast by ₹500, how is it rectified after the difference is put in a Suspense Account?", answer: "Purchases A/c has been debited ₹500 too little, a one-sided error, so Purchases A/c is debited ₹500 and Suspense A/c is credited ₹500.", topicId: 'rectification-of-errors', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-185', question: "How would you rectify a credit sale of ₹3,000 to Mohan that was recorded in the purchases book?", answer: "Debit Mohan ₹6,000, credit Purchases ₹3,000 and credit Sales ₹3,000. Mohan was credited ₹3,000 when Mohan should have been debited ₹3,000, so ₹6,000 is needed to reverse the error and record it correctly.", topicId: 'rectification-of-errors', options: ['vouchers', 'comprehensive'], difficulty: 'complex' },
  { id: 'v11-186', question: "How does rectifying an error affect the profit?", answer: "Correcting a nominal account changes the profit: if wages of ₹2,000 were wrongly debited to Machinery A/c, rectifying it adds ₹2,000 to wages and lowers profit by ₹2,000. Errors that involve only personal or real accounts do not change the profit.", topicId: 'rectification-of-errors', options: ['comprehensive'], difficulty: 'complex' },
  { id: 'v11-187', question: "How does rectification differ before and after the trial balance is prepared?", answer: "Before the trial balance, a one-sided error is corrected by a note or a single entry on the correct side of the account concerned. After the trial balance, when the difference is in a Suspense Account, every one-sided error is corrected by a journal entry with Suspense A/c as the other side.", topicId: 'rectification-of-errors', options: ['vouchers', 'comprehensive'], difficulty: 'complex' },
  { id: 'v11-188', question: "Why should the Suspense Account not be left with a balance?", answer: "It only records an unexplained difference, so any balance left means some errors are still unfound. Once all the errors are rectified, it closes to nil.", topicId: 'rectification-of-errors', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },

  // Depreciation.
  { id: 'v11-189', question: "What is depreciation?", answer: "Depreciation is the gradual and permanent fall in the value of a fixed asset because of use, the passage of time or obsolescence, spread as an expense over its useful life.", topicId: 'depreciation', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-190', question: "What are the causes of depreciation?", answer: "Wear and tear from use, the passage of time, obsolescence when better technology arrives, the expiry of legal rights such as a lease or patent, and depletion of wasting assets such as mines.", topicId: 'depreciation', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-191', question: "Why is depreciation charged?", answer: "To match the cost of the asset with the revenue it helps to earn each year, to show the asset at a fair value in the Balance Sheet, and to keep funds in the business for replacing it. Without it, profit would be overstated.", topicId: 'depreciation', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-192', question: "Which factors decide the amount of depreciation?", answer: "The cost of the asset, its estimated useful life, its estimated residual (scrap) value, and the method of depreciation chosen.", topicId: 'depreciation', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-193', question: "Which method of depreciation did you use, and why?", answer: "Name your method and give a reason that fits the asset: for example, the straight line method for furniture, because it gives the same benefit every year and the method is simple. For machinery or a computer, which lose more value in the early years, I would choose the written down value method.", topicId: 'depreciation', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-194', question: "What is the straight line method of depreciation?", answer: "The same amount, worked out on the original cost, is charged every year: the cost minus the residual value, divided by the useful life in years.", topicId: 'depreciation', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-195', question: "What is the written down value method of depreciation?", answer: "A fixed percentage is charged on the book value of the asset at the start of each year, so the amount of depreciation falls every year.", topicId: 'depreciation', options: ['vouchers', 'comprehensive'], difficulty: 'easy' },
  { id: 'v11-196', question: "How do the straight line and written down value methods compare?", answer: "Under the straight line method the charge is the same every year and the asset can be written down to its scrap value, while under the written down value method the charge falls every year and the book value never reaches nil. The written down value method suits assets whose repairs rise with age, because the total of depreciation and repairs stays fairly even.", topicId: 'depreciation', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-197', question: "A machine costs ₹1,00,000, has a scrap value of ₹10,000 and a life of 9 years: what is the yearly depreciation by the straight line method?", answer: "₹1,00,000 minus ₹10,000 is ₹90,000, and spread over 9 years that is ₹10,000 a year.", topicId: 'depreciation', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-198', question: "What is the second year's depreciation on an asset costing ₹50,000 at 10% by the written down value method?", answer: "The first year's depreciation of ₹5,000 leaves a book value of ₹45,000, so the second year's depreciation is 10% of ₹45,000, which is ₹4,500.", topicId: 'depreciation', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-199', question: "How did you calculate depreciation on an asset bought during the year?", answer: "I charged it only for the months it was in use: for furniture of ₹24,000 bought on 1 October at 10% per annum, the charge up to 31 March is ₹2,400 for a full year times 6 months out of 12, which is ₹1,200.", topicId: 'depreciation', options: ['comprehensive'], difficulty: 'complex' },
  { id: 'v11-200', question: "What costs are included in the cost of an asset for depreciation?", answer: "The purchase price and every cost of bringing the asset into working condition, such as freight, installation charges and taxes that cannot be claimed back. For a machine bought for ₹80,000 with ₹4,000 freight and ₹6,000 installation, the cost is ₹90,000.", topicId: 'depreciation', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-201', question: "What is a Provision for Depreciation Account?", answer: "Depreciation is credited to a Provision for Depreciation (accumulated depreciation) Account instead of the asset account, so the asset stays at its original cost and the total depreciation is shown separately. In the Balance Sheet the provision is deducted from the cost of the asset.", topicId: 'depreciation', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-202', question: "How do you find the profit or loss on the sale of an asset?", answer: "Compare the sale price with the book value on the date of sale: a machine with a book value of ₹38,000 sold for ₹35,000 gives a loss of ₹3,000, which is debited to the Profit and Loss Account. Where a provision for depreciation is kept, the asset and its accumulated depreciation are first transferred to an Asset Disposal Account.", topicId: 'depreciation', options: ['comprehensive'], difficulty: 'complex' },
  { id: 'v11-203', question: "Is depreciation a cash expense?", answer: "No; it is a non-cash expense, because no money is paid out when it is charged. It still reduces profit, which keeps that amount in the business instead of letting it be withdrawn.", topicId: 'depreciation', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-204', question: "Why is land not depreciated?", answer: "Land has an unlimited useful life and does not wear out with use, so it is not depreciated. A building on the land does wear out, so the building is depreciated.", topicId: 'depreciation', options: ['comprehensive'], difficulty: 'medium' },

  // Provisions and reserves.
  { id: 'v11-205', question: "What is a provision?", answer: "A provision is a charge against profit for a known liability or an expected loss whose exact amount cannot be determined, such as a provision for doubtful debts or for taxation.", topicId: 'provisions-and-reserves', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-206', question: "What is a reserve?", answer: "A reserve is a part of profit set aside and kept in the business to strengthen its financial position or to meet future needs. It is an appropriation of profit, not a charge against it.", topicId: 'provisions-and-reserves', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-207', question: "What is the difference between a provision and a reserve?", answer: "A provision is a charge against profit and must be made even when there is a loss, while a reserve is an appropriation of profit made only when there is a profit. A provision is deducted from the asset concerned or shown as a liability, while a reserve is added to the owner's funds.", topicId: 'provisions-and-reserves', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-208', question: "What are some examples of provisions?", answer: "Provision for doubtful debts, provision for depreciation, provision for repairs and renewals, and provision for taxation.", topicId: 'provisions-and-reserves', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-209', question: "What is a general reserve?", answer: "A general reserve is created for no specific purpose, to strengthen the business and meet unknown future needs. It can be used for any purpose.", topicId: 'provisions-and-reserves', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-210', question: "What is a specific reserve?", answer: "A specific reserve is created for a particular purpose, such as a dividend equalisation reserve or a debenture redemption reserve, and can be used only for that purpose.", topicId: 'provisions-and-reserves', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-211', question: "What is the difference between a revenue reserve and a capital reserve?", answer: "A revenue reserve is created out of profits from normal operations and can be used for any purpose, including distribution. A capital reserve is created out of capital profits, such as the profit on sale of a fixed asset, and is generally not available for distribution as dividend.", topicId: 'provisions-and-reserves', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-212', question: "What is a secret reserve?", answer: "A secret reserve is one not shown in the Balance Sheet, created by understating assets or overstating liabilities, for example by charging excessive depreciation. Because it hides the true financial position, it is generally discouraged.", topicId: 'provisions-and-reserves', options: ['comprehensive'], difficulty: 'complex' },
  { id: 'v11-213', question: "Why must a provision be made even when the business makes a loss?", answer: "A provision covers a loss or liability that has already arisen, such as debts that will probably not be recovered, so leaving it out would overstate the result and the assets. Prudence and matching apply whether the year ends in a profit or a loss.", topicId: 'provisions-and-reserves', options: ['comprehensive'], difficulty: 'complex' },
  { id: 'v11-214', question: "How does creating a reserve affect the net profit and the Balance Sheet?", answer: "A reserve does not reduce net profit, because it is set aside after the profit is found, but it reduces the profit available for withdrawal. In the Balance Sheet it adds to the owner's funds, and the matching assets stay in the business.", topicId: 'provisions-and-reserves', options: ['comprehensive'], difficulty: 'complex' },

  // Final accounts.
  { id: 'v11-215', question: "What are final accounts?", answer: "The Trading Account, the Profit and Loss Account and the Balance Sheet, prepared at the end of the period from the trial balance and the adjustments.", topicId: 'final-accounts', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-216', question: "What is the purpose of the Trading Account?", answer: "It finds the gross profit or gross loss by comparing net sales with the cost of goods sold, that is, opening stock plus net purchases and direct expenses, less closing stock.", topicId: 'final-accounts', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-217', question: "What is gross profit?", answer: "Gross profit is net sales minus the cost of goods sold. With sales of ₹2,00,000 and a cost of goods sold of ₹1,50,000, the gross profit is ₹50,000.", topicId: 'final-accounts', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-218', question: "What is the difference between gross profit and net profit?", answer: "Gross profit is net sales minus the cost of goods sold and comes from the Trading Account. Net profit is gross profit plus other incomes minus all indirect expenses, comes from the Profit and Loss Account, and is added to capital.", topicId: 'final-accounts', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-219', question: "What are direct expenses?", answer: "Direct expenses are incurred in buying goods and bringing them to the place of sale, or in making them, such as carriage inwards, freight inwards, wages, customs duty on imports and factory power. They are debited to the Trading Account.", topicId: 'final-accounts', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-220', question: "What are indirect expenses?", answer: "Indirect expenses are the costs of running and selling, not part of the cost of the goods, such as office rent, salaries, advertisement, carriage outwards, bad debts and depreciation. They are debited to the Profit and Loss Account.", topicId: 'final-accounts', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-221', question: "Why is carriage inwards shown in the Trading Account and carriage outwards in the Profit and Loss Account?", answer: "Carriage inwards is the cost of bringing purchased goods to the shop, so it is part of the cost of the goods. Carriage outwards is the cost of delivering goods to customers, a selling expense, so it goes to the Profit and Loss Account.", topicId: 'final-accounts', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-222', question: "What is the difference between capital expenditure and revenue expenditure?", answer: "Capital expenditure buys or improves a fixed asset whose benefit lasts several years, such as a delivery van, and is shown in the Balance Sheet. Revenue expenditure keeps the business running in the current year, such as fuel for the van, and is charged to the Trading or Profit and Loss Account.", topicId: 'final-accounts', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-223', question: "Is the installation charge of a new machine capital or revenue expenditure?", answer: "Capital expenditure, because it is needed to bring the machine into use, so it is added to the cost of the machine. Repairs to keep an old machine running are revenue expenditure.", topicId: 'final-accounts', options: ['vouchers', 'comprehensive'], difficulty: 'medium' },
  { id: 'v11-224', question: "What is a current asset?", answer: "A current asset is one held to be turned into cash, sold or used up within a year in the normal course of business, such as stock, debtors, prepaid expenses and cash and bank balances.", topicId: 'final-accounts', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-225', question: "What is marshalling of the Balance Sheet?", answer: "Marshalling is arranging the assets and liabilities in a set order: either the order of liquidity, with the most liquid assets and the most urgent liabilities first, or the order of permanence, with the most permanent first. A sole proprietor may use either, as long as it is used consistently.", topicId: 'final-accounts', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-226', question: "Which order did you use for your Balance Sheet, and why?", answer: "Give your choice with a reason: for example, the order of permanence, starting with capital and fixed assets such as furniture and ending with current liabilities and cash, because it shows the long-term base of the business first.", topicId: 'final-accounts', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-227', question: "Why is the Balance Sheet not an account?", answer: "It is a statement of the financial position on one date, listing assets and liabilities, not a record of transactions over a period. So it has no debit and credit sides and no 'To' or 'By'.", topicId: 'final-accounts', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-228', question: "What are closing entries?", answer: "Closing entries transfer the balances of nominal accounts, such as purchases, sales, wages and rent, to the Trading Account or the Profit and Loss Account, so those accounts are closed at the end of the period.", topicId: 'final-accounts', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-229', question: "Why is the net profit different from the increase in the cash balance?", answer: "Profit is worked out on the accrual basis, so credit sales, outstanding expenses and depreciation affect it without any cash moving. Cash also changes because of capital introduced, drawings, loans and the purchase of assets, none of which is a profit or a loss.", topicId: 'final-accounts', options: ['comprehensive'], difficulty: 'complex' },
  { id: 'v11-230', question: "Why is GST not shown as an expense or an income in the Profit and Loss Account?", answer: "A registered business collects output GST on behalf of the government and claims the input GST back as a credit, so neither is its own income or expense. Unused input tax credit is an asset and the net output tax payable is a liability.", topicId: 'final-accounts', options: ['vouchers', 'comprehensive'], difficulty: 'complex' },

  // Final accounts with adjustments.
  { id: 'v11-231', question: "What are adjustments, and why are they needed?", answer: "Adjustments are items known at the end of the period but not yet recorded in the books, such as closing stock, outstanding expenses or depreciation. They are made so that the final accounts show the true profit and financial position on the accrual basis.", topicId: 'final-accounts-adjustments', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-232', question: "Why does every adjustment appear twice in the final accounts?", answer: "Each adjustment has a debit and a credit, so it affects two places: usually once in the Trading or Profit and Loss Account and once in the Balance Sheet. For example, outstanding wages are added to wages in the Trading Account and shown as a current liability.", topicId: 'final-accounts-adjustments', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-233', question: "How is closing stock treated in the final accounts?", answer: "Closing stock is shown on the credit side of the Trading Account, which reduces the cost of goods sold, and as a current asset in the Balance Sheet. It is valued at cost or net realisable value, whichever is lower.", topicId: 'final-accounts-adjustments', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-234', question: "How are outstanding expenses treated?", answer: "An outstanding salary of ₹3,000 is added to salaries in the Profit and Loss Account and shown as a current liability in the Balance Sheet.", topicId: 'final-accounts-adjustments', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-235', question: "How are prepaid expenses treated?", answer: "Insurance paid in advance is deducted from insurance in the Profit and Loss Account and shown as a current asset in the Balance Sheet.", topicId: 'final-accounts-adjustments', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-236', question: "What is accrued income, and how is it shown?", answer: "Accrued income is income earned but not yet received, such as interest of ₹1,500 due on an investment. It is added to that income in the Profit and Loss Account and shown as a current asset.", topicId: 'final-accounts-adjustments', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-237', question: "How is income received in advance treated?", answer: "Income received for a future period, such as rent for April received in March, is deducted from that income in the Profit and Loss Account and shown as a current liability, because the service is still owed.", topicId: 'final-accounts-adjustments', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-238', question: "Insurance of ₹12,000 was paid on 1 October for one year, and the books close on 31 March: how much is charged to the year?", answer: "Six months belong to this year, so ₹6,000 is charged to the Profit and Loss Account. The other ₹6,000 is prepaid insurance, shown as a current asset.", topicId: 'final-accounts-adjustments', options: ['comprehensive'], difficulty: 'complex' },
  { id: 'v11-239', question: "How are bad debts treated in the final accounts?", answer: "Further bad debts given as an adjustment are debited to the Profit and Loss Account and deducted from debtors in the Balance Sheet. Bad debts already in the trial balance have already reduced debtors, so they go only to the Profit and Loss Account.", topicId: 'final-accounts-adjustments', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-240', question: "Why is a provision for doubtful debts made when nobody knows which debtors will fail to pay?", answer: "Experience shows that some debtors will not pay, so prudence and matching require the expected loss to be charged in the year the sales were made. Debtors are then shown at the amount likely to be collected.", topicId: 'final-accounts-adjustments', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-241', question: "How is the provision for doubtful debts calculated?", answer: "It is a percentage of debtors after deducting further bad debts: debtors of ₹50,000, further bad debts of ₹2,000 and a 5% provision give ₹2,400. The charge to the Profit and Loss Account is the bad debts plus the new provision, less the old provision.", topicId: 'final-accounts-adjustments', options: ['comprehensive'], difficulty: 'complex' },
  { id: 'v11-242', question: "What is interest on capital, and how is it treated?", answer: "Interest on capital is interest allowed on the owner's capital, for example at 6% per annum, to show what the capital could have earned elsewhere. It is debited to the Profit and Loss Account and added to capital in the Balance Sheet, so the owner's total claim is unchanged; only the split between interest and profit changes.", topicId: 'final-accounts-adjustments', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-243', question: "How is a manager's commission on net profit calculated?", answer: "If the manager gets 10% of the net profit after charging the commission, the commission is 10/110 of the profit before it: on ₹1,10,000 that is ₹10,000. If it is 10% of the profit before charging the commission, it is simply ₹11,000.", topicId: 'final-accounts-adjustments', options: ['comprehensive'], difficulty: 'complex' },
  { id: 'v11-244', question: "How are goods taken by the owner for personal use treated in the final accounts?", answer: "Their cost is deducted from purchases in the Trading Account and added to drawings, and the drawings are deducted from capital in the Balance Sheet.", topicId: 'final-accounts-adjustments', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-245', question: "What is an abnormal loss of goods, and how is it treated?", answer: "An abnormal loss, such as stock of ₹20,000 destroyed by fire, is credited to the Trading Account so the gross profit is not distorted, and debited to the Profit and Loss Account. If the insurer admits a claim of ₹15,000, only the uninsured ₹5,000 is debited to the Profit and Loss Account, and the claim is a current asset until received.", topicId: 'final-accounts-adjustments', options: ['comprehensive'], difficulty: 'complex' },
  { id: 'v11-246', question: "How did the adjustments change your net profit?", answer: "Explain with your own figures: for example, an outstanding salary of ₹3,000 and depreciation of ₹2,000 lowered the net profit by ₹5,000, while accrued interest of ₹1,000 raised it, so the net profit fell by ₹4,000 in all.", topicId: 'final-accounts-adjustments', options: ['comprehensive'], difficulty: 'complex' },

  // Incomplete records: the statement of affairs method.
  { id: 'v11-247', question: "What are incomplete records?", answer: "Incomplete records are books not kept on the double entry system, usually by small traders who keep only a cash book and personal accounts of debtors and creditors. They are also called single entry.", topicId: 'incomplete-records', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-248', question: "What is a statement of affairs?", answer: "A statement of affairs lists the assets and liabilities of a business on a date, from whatever information is available, and the excess of the assets over the liabilities is the capital on that date.", topicId: 'incomplete-records', options: ['comprehensive'], difficulty: 'easy' },
  { id: 'v11-249', question: "How is profit found under the statement of affairs method?", answer: "Profit is closing capital plus drawings during the period, minus additional capital introduced, minus opening capital. Each capital figure comes from a statement of affairs.", topicId: 'incomplete-records', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-250', question: "Why are drawings added back and additional capital deducted when finding profit from capital?", answer: "Drawings took money out of the business and lowered the closing capital, though they are not a loss, so they are added back. Additional capital raised the closing capital without being a profit, so it is deducted.", topicId: 'incomplete-records', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-251', question: "Opening capital is ₹2,00,000, closing capital ₹2,60,000, drawings ₹30,000 and additional capital ₹20,000: what is the profit?", answer: "₹2,60,000 plus ₹30,000 minus ₹20,000 minus ₹2,00,000 gives a profit of ₹70,000.", topicId: 'incomplete-records', options: ['comprehensive'], difficulty: 'complex' },
  { id: 'v11-252', question: "What does it mean if closing capital plus drawings is less than opening capital?", answer: "It means the business made a loss, provided no additional capital was introduced: opening capital of ₹1,50,000, closing capital of ₹1,30,000 and drawings of ₹12,000 give a loss of ₹8,000.", topicId: 'incomplete-records', options: ['comprehensive'], difficulty: 'complex' },
  { id: 'v11-253', question: "How would you find the opening capital if the owner did not know it?", answer: "I would prepare an opening statement of affairs, listing the cash, bank, stock, debtors and fixed assets at the start and deducting the creditors and loans. For example, assets of ₹3,40,000 and liabilities of ₹90,000 give an opening capital of ₹2,50,000.", topicId: 'incomplete-records', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-254', question: "What is the difference between a statement of affairs and a Balance Sheet?", answer: "A Balance Sheet is prepared from the ledger balances of complete double-entry books, while a statement of affairs is prepared partly from estimates and other sources. So a Balance Sheet is the more reliable of the two.", topicId: 'incomplete-records', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-255', question: "What are the limitations of incomplete records?", answer: "There is no trial balance to check arithmetical accuracy, no Trading and Profit and Loss Account to show how the profit arose, and asset values are often estimates. Such records are also hard to rely on for tax or a bank loan.", topicId: 'incomplete-records', options: ['comprehensive'], difficulty: 'medium' },
  { id: 'v11-256', question: "Why did you keep complete double-entry books in your project rather than incomplete records?", answer: "Complete books let me check accuracy with a trial balance and prepare a Trading and Profit and Loss Account showing how the profit was earned. The statement of affairs method gives only the total profit, not how it was made.", topicId: 'incomplete-records', options: ['comprehensive'], difficulty: 'complex' },
];

export default VIVA_11;
